import React from 'react';
import { motion } from 'framer-motion';
import './About.css';

const About = () => {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: { staggerChildren: 0.2, delayChildren: 0.2 }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 30 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.6, ease: "easeOut" } }
  };

  const slideInLeft = {
    hidden: { opacity: 0, x: -50 },
    visible: { opacity: 1, x: 0, transition: { duration: 0.6, ease: "easeOut" } }
  };

  const slideInRight = {
    hidden: { opacity: 0, x: 50 },
    visible: { opacity: 1, x: 0, transition: { duration: 0.6, ease: "easeOut" } }
  };

  return (
    <section id="about" className="about-unique">
      <div className="about-bg-pattern"></div>
      <div className="container">
        {/* Header with Timeline Style */}
        <motion.div
          className="about-header-unique"
          variants={containerVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.2 }}
        >
          <motion.div className="header-badge" variants={itemVariants}>
            <span className="badge-icon">👤</span>
            <span className="badge-text">Who Am I?</span>
          </motion.div>
          <motion.h2 className="about-title-unique" variants={itemVariants}>
            <span className="title-about">About</span>
            <span className="title-me">Me</span>
          </motion.h2>
          <motion.p className="about-subtitle-unique" variants={itemVariants}>
            Discover my journey, passion, and vision
          </motion.p>
        </motion.div>

        {/* Main Content Layout */}
        <div className="about-content-unique">
          {/* Left Side - Personal Info with Timeline */}
          <motion.div
            className="about-info-unique"
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, amount: 0.2 }}
            variants={slideInLeft}
          >
            <div className="info-timeline">
              {[
                { icon: "fas fa-birthday-cake", title: "Born", desc: "10 August 2006", detail: "Pune, India" },
                { icon: "fas fa-graduation-cap", title: "Education", desc: "B.Tech AI & Data Science", detail: "VIT Pune (2024-2028)" },
                { icon: "fas fa-database", title: "Current Role", desc: "Database Lead", detail: "CodeChef VIT Pune" },
                { icon: "fas fa-code", title: "Specialization", desc: "Full Stack Development", detail: "AI & Data Science" }
              ].map((item, index) => (
                <motion.div
                  className="timeline-item-unique"
                  key={index}
                  variants={itemVariants}
                >
                  <div className="timeline-dot"></div>
                  <div className="timeline-content">
                    <div className="info-icon">
                      <i className={item.icon}></i>
                    </div>
                    <h4>{item.title}</h4>
                    <p>{item.desc}</p>
                    <span className="info-detail">{item.detail}</span>
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.div>

          {/* Right Side - Story Cards */}
          <motion.div
            className="about-story-unique"
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, amount: 0.2 }}
            variants={slideInRight}
          >
            {/* Introduction Card */}
            <div className="story-card-unique intro-card">
              <div className="card-header">
                <div className="card-emoji">👋</div>
                <h3>Hello There!</h3>
              </div>
              <div className="card-content">
                <p>I'm <strong>Pritish Jadhav</strong>, a passionate B.Tech student specializing in <strong>AI and Data Science</strong> at <strong>VIT Pune</strong>. My curiosity for technology drives me to explore innovative solutions and tackle complex problems.</p>
              </div>
              <div className="card-footer">
                <div className="card-tag">Student</div>
                <div className="card-tag">AI Enthusiast</div>
              </div>
            </div>

            {/* Vision Card */}
            <div className="story-card-unique vision-card">
              <div className="card-header">
                <div className="card-emoji">🎯</div>
                <h3>My Vision</h3>
              </div>
              <div className="card-content">
                <p>To become a successful <strong>tech entrepreneur</strong> who blends engineering innovation with business vision — creating smart, scalable solutions that inspire change and build a better future.</p>
              </div>
              <div className="card-footer">
                <div className="card-tag">Entrepreneur</div>
                <div className="card-tag">Innovator</div>
              </div>
            </div>

            {/* Skills Highlight */}
            <motion.div
              className="skills-highlight-unique"
              variants={containerVariants}
            >
              <h4>Core Strengths</h4>
              <div className="strength-items">
                {[
                  { icon: "🚀", text: "Innovation" },
                  { icon: "💡", text: "Problem Solving" },
                  { icon: "🎯", text: "Leadership" },
                  { icon: "⚡", text: "Adaptability" }
                ].map((strength, index) => (
                  <motion.div
                    className="strength-item"
                    key={index}
                    variants={itemVariants}
                    whileHover={{ scale: 1.1, backgroundColor: "rgba(99, 102, 241, 0.2)" }}
                  >
                    <div className="strength-icon">{strength.icon}</div>
                    <span>{strength.text}</span>
                  </motion.div>
                ))}
              </div>
            </motion.div>
          </motion.div>
        </div>
      </div>
    </section>
  );
};

export default About;
